 assert seal['passed'] is True and seal['verdict_sha256']==PRIVATE_PINS['verdict.json'] and seal['manifest_sha256']==PRIVATE_PINS['manifest.json']
 assert len(m)==EXPECTED['manifest_entries'] and v['delivery_sha256']=={**m,'manifest.json':PRIVATE_PINS['manifest.json']}
